"""Registered staged search spaces and nested chronological training folds."""
from .common import *
def ml_space():
 out=[]
 values={'LinearRegression':[dict(fit_intercept=True),dict(fit_intercept=False)],'Ridge':[dict(alpha=x) for x in [.1,10,100,1000]],'Lasso':[dict(alpha=x,max_iter=2000) for x in [.001,.1]],'ElasticNet':[dict(alpha=.01,l1_ratio=.2,max_iter=2000),dict(alpha=.1,l1_ratio=.8,max_iter=2000)],'HuberRegressor':[dict(epsilon=1.35,alpha=.0001,max_iter=300),dict(epsilon=1.8,alpha=.1,max_iter=300)],'BayesianRidge':[dict(alpha_1=1e-6,lambda_1=1e-6),dict(alpha_1=.001,lambda_1=.001)],'DecisionTreeRegressor':[dict(max_depth=3,min_samples_leaf=32),dict(max_depth=8,min_samples_leaf=64)],'RandomForestRegressor':[dict(n_estimators=60,max_depth=6,min_samples_leaf=16,max_features=.5),dict(n_estimators=120,max_depth=12,min_samples_leaf=32,max_features=1.)],'ExtraTreesRegressor':[dict(n_estimators=60,max_depth=6,min_samples_leaf=16,max_features=.5),dict(n_estimators=120,max_depth=12,min_samples_leaf=32,max_features=1.)],'HistGradientBoostingRegressor':[dict(max_iter=80,max_leaf_nodes=15,learning_rate=.1,min_samples_leaf=40,l2_regularization=1.,loss='squared_error'),dict(max_iter=160,max_leaf_nodes=31,learning_rate=.03,min_samples_leaf=100,l2_regularization=10.,loss='absolute_error')],'LightGBM':[dict(n_estimators=80,num_leaves=7,learning_rate=.1,min_child_samples=100,reg_lambda=10.,colsample_bytree=.7,subsample=.7,subsample_freq=1,objective='regression_l1'),dict(n_estimators=160,num_leaves=31,learning_rate=.03,min_child_samples=40,reg_lambda=1.,colsample_bytree=1.,subsample=1.,subsample_freq=0,objective='regression')],'KNeighborsRegressor':[dict(n_neighbors=5,weights='distance'),dict(n_neighbors=15,weights='distance')],'SVR':[dict(C=1.,epsilon=.1,gamma='scale'),dict(C=10.,epsilon=.3,gamma='scale')]}
 for family,configs in values.items():
  for j,params in enumerate(configs):out.append(dict(id=f'{family}_{j}',family=family,params=params,scaler='standard' if j%2==0 else 'robust',target='residual_EMA',features='full',max_rows=1024 if family in ['KNeighborsRegressor','SVR'] else 24000))
 for target in ['absolute','delta','residual_EMA','residual_Kalman','normalized_delta']:out.append(dict(id='Ridge_target_'+target,family='Ridge',params=dict(alpha=100),scaler='robust',target=target,features='full',max_rows=24000))
 for subset in ['base','no_geometry','no_spatial','no_timing']:out.append(dict(id='Ridge_features_'+subset,family='Ridge',params=dict(alpha=100),scaler='robust',target='residual_EMA',features=subset,max_rows=24000))
 return out

def neural_space(family):
 out=[]
 for j in range(6):
  c=dict(id=family+'_coarse'+str(j),family=family,width=[12,16,24,24,16,12][j] if family=='cnn' else [64,128,128,64,128,64][j],depth=[2,3,2,3,2,4][j] if family=='cnn' else [1,2,2,2,1,2][j],lr=[.001,.0003,.001,.0003,.001,.0003][j],batch=[64,32,64,32,32,64][j],decay=[.0001,.001,.0001,.0001,.001,.0001][j],loss=['mae','huber','mse','huber','mae','huber'][j],kernel=5 if j==2 else 3,residual=j%2==1,latent=[8,16,32,16,8,16][j],beta=[.03,.1,.3,.1,.3,.03][j],anneal=j in [2,3],huber_delta=.5 if j==3 else 1.,normalization='asinh' if j in [3,5] else 'past',condition='no_geometry' if j==4 else 'full',max_epochs=20,patience=6)
  out.append(c)
 return out

def run():
 assert done('audit');m,a,s=data();fs=folds(m);tr,cal,dev,test=partitions(m);register(ROOT/'model_search_space.json',dict(pixel_models=ml_space(),neural={f:neural_space(f) for f in ['cnn','cvae','flow']},temporal=dict(EMA_half=[7,15,30,60,120,240],windows=[2,4,6],damping_days=[30,90,180],kalman_q=[.001,.01,.1],measurement_multiplier=[.5,2],initial_multiplier=[1,10],clip=[2,4],state=['level','trend']),spatial=dict(representations=['pca4','pca8','svd4','robust_pca4','mask_pca4','block16','multiscale4','geometry4'],coefficient_models=['constant','linear','ridge','huber','ema','kalman','RandomForest','ExtraTrees','LightGBM','GaussianProcess','PLS']),quality=dict(algorithms=['Ridge','Huber','RandomForest','ExtraTrees','HistGradientBoosting','Quantile'],target=['log_absolute_error','log_squared_error','relative_error'],truth='Only held-fold predictions, never in-sample expert fit errors'),bounds=dict(pixel_coarse=len(ml_space()),pixel_refinement_max=8,temporal_candidates=30,representation_coarse=8,coefficient_refinements=22,neural_coarse_per_family=6,neural_refinement_per_family=2,neural_final_configs_per_family=2,full_training_seeds=[SEED,SEED+1,SEED+2],inference_draws=32)))
 register(ROOT/'manifests/research_protocol.json',dict(version=VERSION,dataset=DATASET,split=SPLIT,Stage2='SUSPENDED: no seismic/fusion/eruption modeling, no new Stage2 files',train='Exactly inherited V6 training targets/cutoffs',internal_cv='early2016 train<2016;late2018 train<2018;region2018 excludes southeast_asia training and tests its2018–19 examples; all validation targets remain in inherited train population',screen='late2018 one metadata-selected target per origin; refine only top4 families and evaluate family champions over all3folds',hyperparameter_selection='Internal CV macro-volcano MAE, or future-field CRPS for neural distributions; equal fold weighting. Never2023 or old assessed outcomes',calibration2022='Out-of-sample forecasts from pre2020 fits; variance scaling and learned fusion, quality-head evaluation only',final2023='Locked development assessment, not hyperparameter tuning or shortlist changes',old_assessments='Previously inspected V6–V8, exploratory only. Peru not scored; no new independent population',eligible_history='Exactly same six actual acquisitions for every model; choosing a shorter subset is a model parameter, old12/18map references excluded from primary comparison',preprocessing='Every learned scaler/basis/target scale fit training rows within each fold; no future target basis at inference',reliability='Expert errors from chronological OOF fits; hyperparameter reuse may impart selection optimism, checked against separately OOS2022 errors. Final error head never uses2023 or assessment labels',fusion='Nested/OOF expert predictions and independently OOS2022 blending targets. Bounded2branch shortlist;3branches only if >=.5% OOF gain OR residual correlation<.95; compare four maps vs3+reliability',finalists='Prelock selected by internal CV plus complementary error patterns; no post2023 winner rerun',metrics='Physical signed LOSmm, finite historical+future mask, training-fixed extremes, future coverage>=90% for map-event labels; no interpolated truth',multiplicity='Family shortlists registered before final assessment; simultaneous frame/block bootstrap bounds and Bonferroni sensitivity for finalists; tiny descriptive changes not promotion',resources=dict(CPU_threads=2,GPU_jobs=1,pixel_training_sample=32,max_kernel_rows=1024,max_GPR_latent_cases=256,neural_screen_epochs=20,refinement_epochs=40,full_epoch_limit=60,phase_and_model_resume=True),promotion='No frozen replacement; requires new independent evidence, stable seeds, meaningful gains and safety/chronology/support; no confirmatory assessment in V9'))
 register(ROOT/'manifests/thresholds.json',readjson(V7/'manifests/thresholds.json'));rows=[]
 for name,fit,val in fs:rows.append(dict(population=name,training_pairs=len(fit),training_volcanoes=m.iloc[fit].volcano.nunique(),validation_pairs=len(val),validation_origins=m.iloc[val][['source_id','origin_day']].drop_duplicates().shape[0],validation_volcanoes=m.iloc[val].volcano.nunique(),latest_training_target=date(m.iloc[fit].target_day.max()),earliest_validation_origin=date(m.iloc[val].origin_day.min())))
 csv(ROOT/'manifests/internal_folds.csv',rows);writejson(ROOT/'manifests/fold_indices.json',{name:dict(train=fit.tolist(),validation=val.tolist()) for name,fit,val in fs});csv(ROOT/'evaluation_registry.csv',[dict(population=n,pairs=len(ii),origins=m.iloc[ii][['source_id','origin_day']].drop_duplicates().shape[0],volcanoes=m.iloc[ii].volcano.nunique(),version=VERSION,selection_allowed=n=='training',evidence='search-only' if n=='training' else 'calibration/blending only' if n=='cal2022' else 'locked development assessment' if n=='dev2023' else 'previously inspected exploratory assessment') for n,ii in [('training',tr),('cal2022',cal),('dev2023',dev),('old_assessment',test)]]);finish('protocol',parents=protect());print('V9 PROTOCOL REGISTERED',rows,flush=True)
if __name__=='__main__':run()
